import hashlib,json,os,shutil,statistics,subprocess,tempfile,time
from pathlib import Path
os.sched_setaffinity(0,{0})
root=Path('build/review-j13-performance').resolve();root.mkdir(exist_ok=True)
parent=Path('build/review-j12/release').resolve();candidate=Path('build/review-j13/release').resolve()
frozen=Path('build/review-j12-performance-inputs').resolve()
output=Path('/tmp/mus-review-j13-performance.json')
data={'parent_commit':'f723699','method':'Three alternating paired runs on CPU0, five extra pairs if median wall time >=20% or child peak RSS >=25%. Frozen 500it seed7 policies. New TXT v2 decisions match binary; historical v1 may differ on zero mass and cause different matches. V1 on both builds is an unchanged-semantics control. Existing training compared by checkpoint/value identity. C wait4 launcher measures actual child RSS without Python parent peak. No other own builds/tests during measurement. Game_seconds excludes loading/report. No claim of policy strength or convergence.','inputs':{},'runs':[],'summary':[]}
def digest(path):
 with open(path,'rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def save():
 data['script']=Path(__file__).read_text();data['launcher_source']=Path('/tmp/mus-review-j12-measure.c').read_text()
 data['launcher_build']='cc -O2 -Wall -Wextra -Werror /tmp/mus-review-j12-measure.c -o /tmp/mus-review-j12-measure'
 output.write_text(json.dumps(data,indent=2)+'\n')
def prepare(command):
 p=subprocess.run(command,capture_output=True,text=True);assert p.returncode==0,(command,p.stderr)
for variant in ['ordago','ordago-public']:
 raw=frozen/f'{variant}.cfr';v1=frozen/f'{variant}.txt';v2=root/f'{variant}-v2.txt'
 if not v2.exists():prepare([str(candidate/'mus-solver'),'--format',variant,'--load',str(raw),'--export-strategy',str(v2)])
 for path in [raw,v1,v2]:data['inputs'][str(path)]={'bytes':path.stat().st_size,'sha256':digest(path)}
# Existing test fixtures have known nonzero mass; preserve all JSON decisions.
def call(group,version,repeat,args,exe='mus-match-eval'):
 command=[str((parent if version=='parent' else candidate)/exe),*args]
 rss_path=root/'last-rss.txt';timed=['/tmp/mus-review-j12-measure',str(rss_path),*command]
 with tempfile.TemporaryFile(mode='w+') as out,tempfile.TemporaryFile(mode='w+') as err:
  start=time.perf_counter();pid=os.posix_spawn(timed[0],timed,os.environ,file_actions=[(os.POSIX_SPAWN_DUP2,out.fileno(),1),(os.POSIX_SPAWN_DUP2,err.fileno(),2)])
  _,status,usage=os.wait4(pid,0);elapsed=time.perf_counter()-start;out.seek(0);err.seek(0);stdout=out.read();stderr=err.read()
 assert status==0,(command,status,stderr)
 row={'group':group,'version':version,'repeat':repeat,'command':command,'wall_seconds':elapsed,'peak_rss_kib':int(rss_path.read_text())}
 if exe=='mus-match-eval':
  result=json.loads(stdout);row['game_seconds']=result.pop('seconds')
  row['result_sha256']=hashlib.sha256(json.dumps(result,sort_keys=True,separators=(',',':')).encode()).hexdigest()
  row.update({k:result[k] for k in ['matches','wins','hands','decisions','checksum']})
  row['methods_a']={}
  for r in result['coverage']:
   if r['policy']==0 and r['dimension']=='phase':row['methods_a'][r['method']]=row['methods_a'].get(r['method'],0)+r['count']
 else:row['stdout']=stdout
 data['runs'].append(row);save();print(group,version,repeat,elapsed,row.get('game_seconds'),row['peak_rss_kib'],flush=True);return row

def summary(group,confirmation=False):
 rows=[r for r in data['runs'] if r['group']==group and (r['repeat']>3)==confirmation]
 s={'group':group,'confirmation':confirmation}
 for field in ['wall_seconds','peak_rss_kib']+(['game_seconds'] if 'game_seconds' in rows[0] else []):
  a=statistics.median(r[field] for r in rows if r['version']=='parent');b=statistics.median(r[field] for r in rows if r['version']=='candidate')
  s[field]={'parent':a,'candidate':b,'change_percent':100*(b/a-1)}
 s['trigger']=s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25
 data['summary'].append(s);save();print(s,flush=True);return s['trigger']

for group in ['train-public','train-score','legacy-v1-control','public-v1-control','legacy-v2','public-v2']:
 reference=None
 def pair(repeat):
  global reference
  for version in (['parent','candidate'] if repeat%2 else ['candidate','parent']):
   if group=='train-public':
    checkpoint=root/f'train-{repeat}-{version}.cfr'
    row=call(group,version,repeat,['--format','ordago-public','--iterations','500','--seed','7','--save',str(checkpoint)],'mus-solver')
    h=digest(checkpoint);checkpoint.unlink()
   elif group=='train-score':
    destination=root/f'table-{repeat}-{version}'
    row=call(group,version,repeat,['--format','ordago-score','--score','35:35','--iterations','1000','--evaluation-samples','10000','--seed','7','--continuation',str(destination)],'mus-solver')
    h={p.name:digest(p) for p in destination.iterdir() if p.name=='values.txt' or p.name.endswith('.cfr.zst')}
    shutil.rmtree(destination)
   else:
    variant='ordago-public' if group.startswith('public') else 'ordago'
    txt=root/f'{variant}-v2.txt' if group.endswith('-v2') and version=='candidate' else frozen/f'{variant}.txt'
    row=call(group,version,repeat,['--strategy-a',str(txt),'--opponent','three','--score','0:0','--matches','10000' if group.startswith('public') else '1000','--seed','7'])
    h=row['result_sha256'] if group.endswith('-control') else None
   if h is not None:
    if reference is None:reference=h
    assert h==reference,(group,version)
    row['unchanged_artifacts_or_results']=True
    row['checked_sha256']=h
   save()
 for repeat in range(1,4):pair(repeat)
 if summary(group):
  for repeat in range(4,9):pair(repeat)
  if summary(group,True):
   data['blocked_group']=group;save();break
else:data['blocked_group']=None;save()

